/// plain-text reply — a tool_call here would re-spawn jobs on wrap.
final _turns = [
  [
    {'text': 'launching ten background jobs for p573'},
    for (var i = 1; i <= 10; i++)
      {
        'tool_call': {
          'id': 'c1-$i',
          'name': 'bash',
